    /**
     * Tests whether every character of the delimiter stays itself when individually escaped and read back. The letters used by control-character escape
     * sequences ({@code r}, {@code n}, {@code t}, {@code b}, {@code f}) unescape to the control character, not to the letter, so a delimiter containing one of
     * them cannot have a straddling prefix escaped losslessly and keeps the historical unescaped output.
     */
    private static boolean isDelimiterStraddleEscapable(final char[] delimiter) {
        for (final char ch : delimiter) {
            if (ch == 'r' || ch == 'n' || ch == 't' || ch == 'b' || ch == 'f') {
                return false;
            }
        }
        return true;
    }

    /**
     * Returns true if the given character is a line break character.
     *
     * @param c The character to check.
     * @return true if {@code c} is a line break character.
     */
    private static boolean isLineBreak(final char c) {
        return c == Constants.LF || c == Constants.CR;
    }

    /**
     * Returns true if the given character is a line break character.
     *
     * @param c The character to check, may be null.
     * @return true if {@code c} is a line break character (and not null).
     */
    private static boolean isLineBreak(final Character c) {
        return c != null && isLineBreak(c.charValue()); // Explicit unboxing is intentional
    }

    /** Same test as in as {@link String#trim()}. */
    private static boolean isTrimChar(final char ch) {
        return ch <= Constants.SP;
    }

    /** Same test as in as {@link String#trim()}. */
    private static boolean isTrimChar(final CharSequence charSequence, final int pos) {
        return isTrimChar(charSequence.charAt(pos));
    }

